  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills pipes within the specified distance from source using BFS-style expansion. Water propagates along pipes only when adjacent pipes have matching connection directions (one pipe's direction must be the opposite of the other). The source termination cell is already filled before this method is called.
   * Algorithm:
   *   1. Initialize BFS queue with the source cell's neighbor in the pointingTo direction
   *   2. For each distance step from 1 to distance:
   *      a. For each cell at current BFS frontier:
   *         - For each connection direction of the cell's pipe:
   *           - Calculate neighbor coordinate using direction offset
   *           - If neighbor is a FillableCell with a pipe:
   *             - Check if connections match (neighbor's connection opposite to current direction)
   *             - If match and not yet visited, add to next frontier
   *      b. If the SINK termination cell is reached, stop early
   *   3. Mark all visited cells as filled
   *   4. Update prevFilledTiles with count of newly filled tiles
   * Related Features: cells, sourceCell, filledTiles, prevFilledTiles
   * Related Classes: Coordinate, Direction, FillableCell, Pipe, TerminationCell
   * Input: distance (int) - how far water should flow
   * Output: None
   * Pre-condition: distance >= 0; sourceCell is already filled
   * Post-condition: Pipes within distance from source are filled if connections match; prevFilledTiles is updated with the count of newly filled tiles
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance < 0) {
      prevFilledTiles = 0;
      return;
    }
    
    boolean[][] visited = new boolean[getRows()][getCols()];
    EList<Coordinate> currentFrontier = new BasicEList<Coordinate>();
    
    TerminationCell source = getSourceCell();
    if (source == null || source.getPointingTo() == null) {
      prevFilledTiles = 0;
      return;
    }
    
    Coordinate sourceCoord = source.getCoord();
    Direction pointingTo = source.getPointingTo();
    
    // Calculate neighbor coordinate based on pointingTo direction
    int dr = 0, dc = 0;
    switch (pointingTo.getValue()) {
      case Direction.UP_VALUE:
        dr = -1; dc = 0; break;
      case Direction.DOWN_VALUE:
        dr = 1; dc = 0; break;
      case Direction.LEFT_VALUE:
        dr = 0; dc = -1; break;
      case Direction.RIGHT_VALUE:
        dr = 0; dc = 1; break;
    }
    
    int startRow = sourceCoord.getRow() + dr;
    int startCol = sourceCoord.getCol() + dc;
    
    if (startRow >= 0 && startRow < getRows() && startCol >= 0 && startCol < getCols()) {
      Cell startCell = getCell()[startRow][startCol];
      if (startCell instanceof FillableCell && ((FillableCell) startCell).getPipe() != null) {
        Pipe startPipe = ((FillableCell) startCell).getPipe();
        Direction oppositeOfPointing = getOppositeDirection(pointingTo);
        if (startPipe.getConnections().contains(oppositeOfPointing)) {
          Coordinate startCoord = Pa19Factory.eINSTANCE.createCoordinate();
          startCoord.setRow(startRow);
          startCoord.setCol(startCol);
          currentFrontier.add(startCoord);
          visited[startRow][startCol] = true;
        }
      }
    }
    
    int newlyFilled = 0;
    boolean sinkReached = false;
    
    for (int step = 1; step <= distance && !currentFrontier.isEmpty() && !sinkReached; step++) {
      EList<Coordinate> nextFrontier = new BasicEList<Coordinate>();
      
      for (Coordinate coord : currentFrontier) {
        int r = coord.getRow();
        int c = coord.getCol();
        Cell cell = getCell()[r][c];
        
        if (!(cell instanceof FillableCell)) continue;
        FillableCell fc = (FillableCell) cell;
        Pipe pipe = fc.getPipe();
        if (pipe == null) continue;
        
        for (Direction dir : pipe.getConnections()) {
          int nr = r, nc = c;
          switch (dir.getValue()) {
            case Direction.UP_VALUE: nr = r - 1; break;
            case Direction.DOWN_VALUE: nr = r + 1; break;
            case Direction.LEFT_VALUE: nc = c - 1; break;
            case Direction.RIGHT_VALUE: nc = c + 1; break;
          }
          
          if (nr < 0 || nr >= getRows() || nc < 0 || nc >= getCols()) continue;
          if (visited[nr][nc]) continue;
          
          Cell neighborCell = getCell()[nr][nc];
          
          // Check if sink termination cell is reached
          if (neighborCell instanceof TerminationCell && neighborCell == getSinkCell()) {
            TerminationCell sink = (TerminationCell) neighborCell;
            Direction opposite = getOppositeDirection(dir);
            if (sink.getPointingTo() == opposite) {
              sinkReached = true;
            }
            continue;
          }
          
          if (neighborCell instanceof FillableCell) {
            FillableCell neighborFc = (FillableCell) neighborCell;
            Pipe neighborPipe = neighborFc.getPipe();
            if (neighborPipe != null) {
              Direction opposite = getOppositeDirection(dir);
              if (neighborPipe.getConnections().contains(opposite)) {
                Coordinate nextCoord = Pa19Factory.eINSTANCE.createCoordinate();
                nextCoord.setRow(nr);
                nextCoord.setCol(nc);
                nextFrontier.add(nextCoord);
                visited[nr][nc] = true;
              }
            }
          }
        }
      }
      
      // Mark cells in current frontier as filled
      for (Coordinate coord : currentFrontier) {
        Cell cell = getCell()[coord.getRow()][coord.getCol()];
        if (cell instanceof FillableCell) {
          FillableCell fc = (FillableCell) cell;
          Pipe p = fc.getPipe();
          if (p != null && !p.isFilled()) {
            p.setFilled(true);
            newlyFilled++;
          }
        }
      }
      
      if (sinkReached) {
        getSinkCell().setFilled(true);
        break;
      }
      
      currentFrontier = nextFrontier;
    }
    
    // If sink was not reached and there are remaining cells in the frontier (from the last step that didn't execute)
    // Actually, the loop already processes each step's frontier. If the loop ends because step > distance,
    // the last frontier has already been processed. So we're good.
    
    prevFilledTiles = newlyFilled;
  }

